import json
import subprocess
from pathlib import Path

import yaml

workflow_paths = sorted(Path('.github/workflows').glob('*.yml'))
shell_steps = []

def inspect(value, workflow):
    if isinstance(value, dict):
        for key, child in value.items():
            if key == 'run' and isinstance(child, str):
                subprocess.run(['bash', '-n'], input=child, text=True, check=True)
                shell_steps.append({'workflow': str(workflow), 'chars': len(child)})
            else:
                inspect(child, workflow)
    elif isinstance(value, list):
        for child in value:
            inspect(child, workflow)

for path in workflow_paths:
    yaml.safe_load(path.read_text(encoding='utf-8'))
    inspect(yaml.safe_load(path.read_text(encoding='utf-8')), path)

print(json.dumps({'workflows': len(workflow_paths), 'embedded_shell_steps': len(shell_steps), 'validated_with': 'bash -n', 'status': 'PASS'}))
